<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Document\Theme\Domain\ThemeRef;
use Civi\Lughauth\Features\Document\Template\Domain\ValueObject\Accessor\TemplateThemeAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TemplateThemeAccessor trait.
 *
 * Covers null default, string/VO assignment via withTheme,
 * getTheme/theme accessors, and isThemeChanged with/without original.
 */
class TemplateThemeAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withTheme creates a new instance with the Theme set
     * from a string value, and getTheme returns the primitive string.
     */
    public function testWithThemeFromString(): void
    {
        // Arrange
        $holder = new ImplWithTemplateThemeAccessorUnitTest();

        // Act
        $result = $holder->withTheme(new ThemeRef('one'));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(new ThemeRef('one'), $result->getTheme());
    }
    /**
     * Asserts that withtheme has access to the value object
     * from a string value, and getTheme returns the primitive string.
     */
    public function testWithThemeFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTemplateThemeAccessorUnitTest();

        // Act
        $result = $holder->withTheme(new ThemeRef('one'));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(new ThemeRef('one'), $result->theme()->value());
    }
    public function testChangedTheme(): void
    {
        // Arrange
        $holder = new ImplWithTemplateThemeAccessorUnitTest();
        $original = $holder->withTheme( new ThemeRef('one'));
        $same = $holder->withTheme( new ThemeRef('one'));
        $modified = $holder->withTheme(new ThemeRef('other'));

        // Act
        $unchanged = $holder->isThemeChanged();
        $withSame = $original->isThemeChanged( $same );
        $withDiferent = $original->isThemeChanged( $modified );

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTemplateThemeAccessorUnitTest
{
  use TemplateThemeAccessor;
}
